int goto_direct(int x) { if(x) goto done; return 0; done: return 1; }
int goto_braced(int x) { if(x) { goto done; } return 0; done: return 1; }
int goto_standalone(int x) { goto done; done: return x; }
int for_direct(int x) { int n=0; if(x) for(int i=0;i<x;i++) n++; else for(int j=0;j<x;j++) n--; return n; }
int for_braced(int x) { int n=0; if(x) { for(int i=0;i<x;i++) n++; } else { for(int j=0;j<x;j++) n--; } return n; }
int while_direct(int x) { if(x) while(x>1) { if(x==2) break; x--; } return x; }
int do_direct(int x) { if(x) do { if(x==2) break; x--; } while(x); return x; }
int switch_direct(int x) { if(x) switch(x) { case 1: if(x) x++; break; default: x--; } return x; }
int ternary_direct(int x) { if(x) x ? x++ : x--; return x; }
int ternary_parenthesized(int x) { if(x) (x ? x++ : x--); return x; }
int ternary_return(int x) { if(x) return x ? 1 : 2; return 0; }
int logical_direct(int a,int b) { if(a) a && b; else a || b; return a; }
int nested_if(int x) { if(x) if(x>1) return 1; return 0; }
int else_if_comment(int x) { if(x) return 1; else /* comment */ if(x<0) return -1; return 0; }
int else_body_comment(int x) { if(x) return 1; else /* comment */ while(x) x++; return x; }
int lambda_direct(int x) { if(x) [x]() { if(x) return 1; return 0; }; return 0; }
int lambda_parenthesized(int x) { if(x) ([x]() { if(x) return 1; return 0; }); return 0; }

